/// MS Sans Serif 8pt bitmap font data.
/// Glyph bitmaps extracted from reference screenshot (original Windows game).
/// Fallback glyphs from Wine's sserife.fon (LGPL 2.1) for chars not in screenshot.
/// Advance widths from scripts/final_widths.json (island analysis + offset correction).
/// Generated by scripts/extract_and_generate_glyphs.py.

/// Per-glyph metrics and bitmap data.
#[derive(Clone, Copy)]
pub struct GlyphData {
    /// Character advance width in pixels
    pub advance: u8,
    /// Horizontal bearing (offset from pen position to left edge of bitmap)
    pub bearing_x: i8,
    /// Vertical bearing (offset from baseline to top edge of bitmap)
    pub bearing_y: i8,
    /// Bitmap width in pixels
    pub width: u8,
    /// Bitmap height in pixels
    pub height: u8,
    /// Bitmap pitch (bytes per row)
    pub pitch: u8,
    /// Offset into BITMAP_DATA where this glyph's rows start
    pub bitmap_offset: u16,
}

/// Font height (tmHeight) = 13px
pub const FONT_HEIGHT: i32 = 13;

/// Font ascent (ascender) = 11px
pub const FONT_ASCENT: i32 = 11;

/// Line spacing (tmHeight + tmExternalLeading) = 16px
/// Source: DrawTextA uses this for line skip
pub const LINE_SPACING: i32 = 16;

